{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "A tocotrienol-rich fraction, a lipophilic polyprenyl chromanol with a long isoprenoid tail, has poor oral bioavailability in humans, supporting low F for the similarly large and lipophilic polyprenyl benzoquinone query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Lycopene, a long linear polyisoprenoid carotenoid, showed only about 2.6% systemic availability from capsules in humans, indicating that large highly lipophilic polyisoprenoid molecules are generally poorly absorbed.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Phytoene, another long polyisoprenoid carotenoid, was estimated at 58.5% bioavailability in humans, providing a contradictory example that some flexible polyisoprenoids can be well absorbed, though its lack of a polar quinone head limits direct transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a large, highly lipophilic polyprenyl benzoquinone (ubiquinone-9-like). Analogous long-chain isoprenoid lipids such as tocotrienols and lycopene show poor oral bioavailability, and the very high lipophilicity and large size make F >= 20% less likely.",
  "evidence_gaps": [
    "No direct oral bioavailability record for ubiquinone-9/CoQ9 itself.",
    "Carotenoid bioavailability is highly formulation- and food-matrix-dependent, so quantitative transfer to a benzoquinone is uncertain.",
    "The F >= 20% threshold was not directly measured in the closest analogues."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

